  "projects.titleHighlight": { en: "BIM Projects", hi: "BIM परियोजनाएँ", ar: "مشاريع BIM", fr: "BIM Emblématiques", de: "BIM-Projekte", es: "BIM Emblemáticos", zh: "BIM项目", ja: "BIMプロジェクト" },
  "projects.titleEnd": { en: "Worldwide", hi: "विश्वव्यापी", ar: "حول العالم", fr: "dans le Monde", de: "Weltweit", es: "en el Mundo", zh: "全球范围", ja: "世界中で" },
  "projects.desc": { en: "Explore our portfolio of mega projects delivered with precision BIM methodology across diverse sectors.", hi: "विविध क्षेत्रों में सटीक BIM कार्यप्रणाली से पूर्ण हमारी मेगा परियोजनाओं का अन्वेषण करें।", ar: "استكشف محفظتنا من المشاريع الكبرى المنجزة بمنهجية BIM الدقيقة.", fr: "Explorez notre portfolio de méga-projets livrés avec une méthodologie BIM de précision.", de: "Entdecken Sie unser Portfolio an Megaprojekten, die mit präziser BIM-Methodik geliefert wurden.", es: "Explore nuestra cartera de mega proyectos entregados con metodología BIM de precisión.", zh: "探索我们以精确BIM方法论在多元行业交付的大型项目组合。", ja: "多様なセクターで精密BIMメソドロジーにより納品したメガプロジェクトのポートフォリオをご覧ください。" },
  "projects.all": { en: "All", hi: "सभी", ar: "الكل", fr: "Tous", de: "Alle", es: "Todos", zh: "全部", ja: "すべて" },
