  "careers.professionalDetails": { en: "Professional Details", hi: "पेशेवर विवरण", ar: "التفاصيل المهنية", fr: "Détails professionnels", de: "Berufliche Details", es: "Detalles profesionales", zh: "专业详情", ja: "職務経歴" },
  "careers.currentRole": { en: "Current Role / Title", hi: "वर्तमान भूमिका / शीर्षक", ar: "الوظيفة الحالية", fr: "Poste actuel", de: "Aktuelle Position", es: "Cargo actual", zh: "当前职位", ja: "現在の役職" },
  "careers.experience": { en: "Years of Experience", hi: "अनुभव के वर्ष", ar: "سنوات الخبرة", fr: "Années d'expérience", de: "Berufserfahrung (Jahre)", es: "Años de experiencia", zh: "经验年限", ja: "経験年数" },
  "careers.education": { en: "Education / Qualification", hi: "शिक्षा / योग्यता", ar: "التعليم / المؤهلات", fr: "Formation / Qualification", de: "Ausbildung / Qualifikation", es: "Educación / Calificación", zh: "教育/资格", ja: "学歴/資格" },
  "careers.portfolio": { en: "Portfolio / Website", hi: "पोर्टफोलियो / वेबसाइट", ar: "الأعمال / الموقع", fr: "Portfolio / Site web", de: "Portfolio / Webseite", es: "Portafolio / Sitio web", zh: "作品集/网站", ja: "ポートフォリオ/ウェブサイト" },
