  "careers.dragDrop": { en: "Drag & drop your resume here, or", hi: "अपना रिज्यूमे यहाँ खींचें और छोड़ें, या", ar: "اسحب وأفلت سيرتك الذاتية هنا، أو", fr: "Glissez-déposez votre CV ici, ou", de: "Lebenslauf hierher ziehen und ablegen, oder", es: "Arrastre y suelte su currículum aquí, o", zh: "将简历拖放到此处，或", ja: "履歴書をここにドラッグ＆ドロップ、または" },
  "careers.browse": { en: "browse", hi: "ब्राउज़ करें", ar: "تصفح", fr: "parcourir", de: "durchsuchen", es: "explorar", zh: "浏览", ja: "参照" },
