  "careers.coverLetterPlaceholder": { en: "Tell us why you're interested in this role, your key achievements, and what you'd bring to our team...", hi: "हमें बताएं कि आप इस भूमिका में क्यों रुचि रखते हैं, आपकी प्रमुख उपलब्धियां और आप हमारी टीम में क्या लाएंगे...", ar: "أخبرنا لماذا أنت مهتم بهذا الدور وإنجازاتك الرئيسية وما ستقدمه لفريقنا...", fr: "Dites-nous pourquoi vous êtes intéressé par ce poste, vos réalisations clés et ce que vous apporteriez...", de: "Erzählen Sie uns, warum Sie an dieser Rolle interessiert sind, Ihre wichtigsten Erfolge und was Sie einbringen würden...", es: "Cuéntenos por qué le interesa este puesto, sus logros clave y lo que aportaría a nuestro equipo...", zh: "告诉我们您为什么对这个职位感兴趣、您的主要成就以及您将为团队带来什么...", ja: "このポジションに興味がある理由、主な実績、チームにもたらすものをお聞かせください..." },
  "careers.requiredFields": { en: "* Required fields. Your data is handled confidentially per our privacy policy.", hi: "* आवश्यक फ़ील्ड। आपका डेटा हमारी गोपनीयता नीति के अनुसार गोपनीय रूप से संभाला जाता है।", ar: "* الحقول المطلوبة. يتم التعامل مع بياناتك بسرية وفقاً لسياسة الخصوصية.", fr: "* Champs obligatoires. Vos données sont traitées conformément à notre politique de confidentialité.", de: "* Pflichtfelder. Ihre Daten werden vertraulich gemäß unserer Datenschutzrichtlinie behandelt.", es: "* Campos obligatorios. Sus datos se manejan confidencialmente según nuestra política de privacidad.", zh: "* 必填字段。您的数据将根据我们的隐私政策保密处理。", ja: "* 必須項目。お客様のデータはプライバシーポリシーに従い機密扱いされます。" },
  "careers.submitApp": { en: "Submit Application", hi: "आवेदन सबमिट करें", ar: "إرسال الطلب", fr: "Soumettre la candidature", de: "Bewerbung einreichen", es: "Enviar solicitud", zh: "提交申请", ja: "応募を提出" },
